import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        int[] b = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }
        for (int i = 0; i < n; i++) {
            b[i] = sc.nextInt();
        }

        int rez = 0;
        int aSum = 0;
        int bSum = 0;
        for (int i = 0; i < n; i++) {
            aSum += a[i];
            bSum += b[i];
            if (a[i] == 1 && b[i] == 0) {
                rez++;
            }
        }

        if (aSum > bSum) {
            System.out.println(1);
        } else if (rez == 0 || aSum == 0 || (aSum == n && bSum == n)) {
            System.out.println(-1);
        } else {
            double val = (double) (bSum - aSum + 1) / rez;
            long result = (long) Math.ceil(val) + 1;
            System.out.println(result);
        }
        sc.close();
    }
}

